inputDetail.command:
Get-ChildItem "D:\Videos\Captures" | Sort-Object LastWriteTime | Select-Object Name, @{Name="MB";Expression={[math]::Round($_.Length/1MB,2)}}, LastWriteTime | Format-Table -AutoSize
Get-Item "D:\Downloads\OG3qUKbv1RPdom_w.mp4" -ErrorAction SilentlyContinue | Select-Object FullName, @{Name="MB";Expression={[math]::Round($_.Length/1MB,2)}}
Get-Command ffmpeg, ffprobe, python -ErrorAction SilentlyContinue | Select-Object Name, Source

$ffprobe = "C:\Program Files\Derivative\TouchDesigner\bin\ffprobe.exe"
if (-not (Test-Path $ffprobe)) {
  $ffprobe = (Get-ChildItem "$env:LOCALAPPDATA\Microsoft\WinGet\Packages\Gyan.FFmpeg*" -Filter "ffprobe.exe" -Recurse | Select-Object -First 1).FullName
}
$ffmpeg = $ffprobe -replace "ffprobe\.exe$", "ffmpeg.exe"
Write-Output "FFMPEG=$ffmpeg"
$vids = @(Get-ChildItem "D:\Videos\Captures\*.mp4") + @(Get-Item "D:\Downloads\OG3qUKbv1RPdom_w.mp4")
foreach ($v in $vids) {
  $dur = & $ffprobe -v error -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 $v.FullName
  Write-Output "$($v.Name) | $([math]::Round([double]$dur, 1))s"
}
